def dump_csv(path,records):
    if not records:return
    with path.open('w') as f:
        w=csv.DictWriter(f,fieldnames=list(records[0]));w.writeheader();w.writerows(records)

def ci(a,groups,seed=1234):
    a=np.asarray(a,float);g=np.asarray(groups);keys=np.unique(g)
    if len(keys)<2:return None
    rng=np.random.default_rng(seed);sums=np.array([a[g==k].sum() for k in keys]);ns=np.array([(g==k).sum() for k in keys]);ix=rng.integers(len(keys),size=(10000,len(keys)))
    return np.quantile(sums[ix].sum(1)/ns[ix].sum(1),[.025,.975]).tolist()

